package com.hs.jxc.ar;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.imports.ImportHandler;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class ReceivablesImportHandler implements ImportHandler {
 private final JdbcTemplate jdbc;private final ReceivablesService service;
 public ReceivablesImportHandler(JdbcTemplate jdbc,ReceivablesService service){this.jdbc=jdbc;this.service=service;}
 public List<String> types(){return List.of("OPENING_AR","OPENING_ADVANCE","CREDIT_RULE");}
 public List<String> columns(String type){return type.equals("CREDIT_RULE")?List.of("targetType","targetId","paymentMode","creditLimit","currency","termDays","dueBasis","dueExtraDays","overduePolicy","graceDays","allowException","effectiveFrom"):List.of("bookId","customerCode","currency","amount","refNo","sourceDate","dueDate");}
 public Row validate(Access a,String type,LocalDate cutoff,int number,Map<String,Object> raw){
  if(type.equals("CREDIT_RULE")){a.require("ar:credit-rule:edit");if(!a.scope().all())throw ApiException.notFound();String target=Inputs.required(raw,"targetType");if(!Set.of("CUSTOMER","GROUP").contains(target))throw Inputs.bad("授信目标不合法");long id=Inputs.id(raw.get("targetId"));if(jdbc.queryForObject("SELECT count(*) FROM "+(target.equals("CUSTOMER")?"md_customer":"md_customer_group")+" WHERE country_id=? AND id=? AND status='ENABLED'",Integer.class,a.requireCountry(),id)!=1)throw ApiException.notFound();var values=new LinkedHashMap<String,Object>(raw);if(!Set.of("CASH_ONLY","CREDIT_ALLOWED").contains(Inputs.required(raw,"paymentMode")))throw Inputs.bad("付款模式不合法");if(Inputs.decimal(raw.get("creditLimit"),4,new BigDecimal("999999999999")).signum()<0)throw Inputs.bad("额度不能为负");LocalDate.parse(Inputs.required(raw,"effectiveFrom"));return new Row(number,values,target+":"+id+":"+Inputs.required(raw,"effectiveFrom"));}
  a.require("ar:receivable:view");long book=Inputs.id(raw.get("bookId"));if(!a.canBook(book))throw ApiException.notFound();var customers=jdbc.queryForList("SELECT id FROM md_customer WHERE country_id=? AND code=? AND status='ENABLED'",Long.class,a.requireCountry(),Inputs.required(raw,"customerCode"));if(customers.size()!=1)throw Inputs.bad("客户不存在或未启用");long customer=customers.getFirst();if(cutoff==null||LocalDate.parse(Inputs.required(raw,"sourceDate")).isAfter(cutoff))throw Inputs.bad("期初截止日期和来源日期不合法");String ref=Inputs.required(raw,"refNo");if(ref.length()>100)throw Inputs.bad("来源编号过长");String currency=Inputs.required(raw,"currency");String base=jdbc.queryForObject("SELECT base_currency FROM fin_book WHERE country_id=? AND id=?",String.class,a.requireCountry(),book);if(!currency.equals(base))throw Inputs.bad("期初币种须为账簿币种，不能推算汇率");BigDecimal amount=Inputs.decimal(raw.get("amount"),4,new BigDecimal("999999999999"));if(amount.signum()<=0)throw Inputs.bad("金额须为明确正数");String table=type.equals("OPENING_AR")?"ar_receivable":"ar_credit_note";if(jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE country_id=? AND (doc_no=? OR opening_ref=?)",Integer.class,a.requireCountry(),ref,ref)>0||jdbc.queryForObject("SELECT count(*) FROM sal_order WHERE country_id=? AND doc_no=?",Integer.class,a.requireCountry(),ref)>0||jdbc.queryForObject("SELECT count(*) FROM ar_receipt WHERE country_id=? AND (doc_no=? OR reference_no=?)",Integer.class,a.requireCountry(),ref,ref)>0)throw new ApiException(409,"SYS_IMPORT_REFERENCE_EXISTS","来源已有系统单据");var values=new LinkedHashMap<String,Object>();values.put("bookId",book);values.put("customerId",customer);values.put("currency",currency);values.put("amount",amount);values.put("refNo",ref);values.put("sourceDate",LocalDate.parse(raw.get("sourceDate").toString()).toString());values.put("dueDate",type.equals("OPENING_AR")?LocalDate.parse(Inputs.required(raw,"dueDate")).toString():cutoff.toString());return new Row(number,values,cutoff+":"+book+":"+customer+":"+ref);
 }
 public Target apply(RequestContext c,Access a,Batch batch,Row row){if(batch.type().equals("CREDIT_RULE")){var v=new LinkedHashMap<>(row.values());var previous=jdbc.queryForList("SELECT id,version FROM ar_credit_rule WHERE country_id=? AND target_type=? AND target_id=? AND status='ACTIVE' ORDER BY version_no DESC,id DESC LIMIT 1 FOR UPDATE",a.requireCountry(),v.get("targetType"),v.get("targetId"));Long old=null;if(!previous.isEmpty()){old=((Number)previous.getFirst().get("id")).longValue();v.put("version",previous.getFirst().get("version"));}var result=service.saveRule(c,old,v);return new Target("AR_CREDIT_RULE",Inputs.id(result.get("id")));}var v=row.values();long source=jdbc.queryForObject("SELECT id FROM sys_import_row WHERE country_id=? AND batch_id=? AND row_no=?",Long.class,a.requireCountry(),batch.id(),row.rowNo());var result=service.importOpening(a,Inputs.id(v.get("bookId")),Inputs.id(v.get("customerId")),v.get("currency").toString(),new BigDecimal(v.get("amount").toString()),v.get("refNo").toString(),batch.cutoffDate(),LocalDate.parse(v.get("dueDate").toString()),source,batch.type().equals("OPENING_ADVANCE"));return new Target(batch.type().equals("OPENING_AR")?"AR_RECEIVABLE":"AR_CREDIT_NOTE",Inputs.id(result.get("id")));}
}
